    public static void consutaISBN(){
        String ISBN =IO.readln("Digite o ISBN do livro: ");
        livros.forEach((key,Livro)->{
            if (ISBN.equals(key)){
                IO.println("<---------- Livros com o ISBN: "+key+"----------->");
                IO.println("Titulo do livro: "+Livro.getTiulo());
                IO.println("Autor do livro: "+Livro.getAutor());
                IO.println("Ano de publicacao: "+Livro.getAno());
                IO.println("----------------------------------------");
            }
        });
    }
    public static void consultaAutor(){
        String Autor=IO.readln("Digite o Autor do livro");
        IO.println("<---------- Livro com o Autor: "+Autor+"----------->");
        livros.forEach((key,Livro)->{
            if (Autor.equals(Livro.getAutor())){
                IO.println("ISBN do livro: "+key);
                IO.println("Titulo do livro: "+Livro.getTiulo());
                IO.println("Ano de publicacao: "+Livro.getAno());
                IO.println("----------------------------------------");
            }
        });
    }
    public static void consutaAno(){
        String Ano=IO.readln("Digite o Ano da consulta");
        IO.println("<---------- Livro com o Ano de publicação: "+Ano+"----------->");
        livros.forEach((key,Livro)->{
            if (Ano.equals(Livro.getAno())){
                IO.println("ISBN do livro: "+key);
                IO.println("Titulo do livro: "+Livro.getTiulo());
                IO.println("Autor do livro: "+Livro.getAutor());
                IO.println("----------------------------------------");
            }
        });
    }
    public static void atualizarDados(){
        String ISBN=IO.readln("Digite o ISBN");
        if (livros.containsKey(ISBN)) {
            IO.println("<----------Atualizar dados de um lvro---------->");
            IO.println("1.Atualizar apenas o Autor");
            IO.println("2.Atualizar apenas o Titulo");
            IO.println("3.Atualizar o ano de publicação");
            IO.println("4.Atualizar o Autor e o Titulo");
            IO.println("5.Atualizar o Titulo e publicação");
            IO.println("6.Atualizar o Autor e o Ano de publicação");
            IO.println("7.Atualizar todos os dados");
            String Dig = IO.readln("Digite sua seleção: ");
            int Sel = Integer.parseInt(Dig);
            switch (Sel) {
                case 1:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String autor = IO.readln("Digite o autor:");
                            livro.setAutor(autor);
                        }
                    });
                    break;
                case 2:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String Titulo = IO.readln("Digite o Titulo:");
                            livro.setTiulo(Titulo);
                        }
                    });
                    break;
                case 3:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String Ano = IO.readln("Digite o Ano:");
                            int Anoint = Integer.parseInt(Ano);
                            livro.setAno(Anoint);
                        }
                    });
                    break;
                case 4:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String autor = IO.readln("Digite o autor:");
                            livro.setAutor(autor);
                            String Titulo = IO.readln("Digite o Titulo:");
                            livro.setTiulo(Titulo);
                        }
                    });
                    break;
                case 5:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String Titulo = IO.readln("Digite o Titulo:");
                            livro.setTiulo(Titulo);
                            String Ano = IO.readln("Digite o Ano:");
                            int Anoint = Integer.parseInt(Ano);
                            livro.setAno(Anoint);
                        }
                    });
                    break;
                case 6:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String autor = IO.readln("Digite o autor:");
                            livro.setAutor(autor);
                            String Ano = IO.readln("Digite o Ano:");
                            int Anoint = Integer.parseInt(Ano);
                            livro.setAno(Anoint);
                        }
                    });
                    break;
                case 7:
                    livros.forEach((key, livro) -> {
                        if (ISBN.equals(key)) {
                            String autor = IO.readln("Digite o autor:");
                            livro.setAutor(autor);
                            String Titulo = IO.readln("Digite o Titulo:");
                            livro.setTiulo(Titulo);
                            String Ano = IO.readln("Digite o Ano:");
                            int Anoint = Integer.parseInt(Ano);
                            livro.setAno(Anoint);
                        }
                    });
                    break;
                default:
                    IO.println("Erro digite novamente :");
                    break;
            }
        } else{
            IO.println("ISBN não cadastrado, tente novamente");
            atualizarDados();
        }
    }
